      paint(a); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high";
      ctx.drawImage(off, cx - R - R * D / (D - 2) * 0 - (R * D / (D - 2) - R), cy - R - (R * D / (D - 2) - R), R * 2 * D / (D - 2), R * 2 * D / (D - 2));
